// Route planner for: The Earth–Venus Shuttle Run
/* jahdb-demo-1.0 route planner - runnable JS */
(function(){
  var legs=[
    ["Earth departure", "3.5"],
    ["Hohmann cruise", "0.8"],
    ["Venus aerocapture", "1.2"]
  ];
  var dv=0;
  legs.forEach(function(l,i){ console.log((i+1)+". "+l[0]+"  delta-v "+l[1]+" km/s"); dv+=Number(l[1]); });
  console.log("total delta-v: "+dv.toFixed(2)+" km/s");
  console.log("OK: route plan complete");
})();

